<?php if(!defined('SW_APP')){http_response_code(404);exit;}
$filter=$_GET['status']??'todos';if(!is_string($filter)||!in_array($filter,['todos','activo','borrador','finalizado'],true))$filter='todos';$rows=raffle_list();$counts=['todos'=>count($rows),'activo'=>0,'borrador'=>0,'finalizado'=>0];foreach($rows as $r)$counts[$r['status']]++;
$filtered=array_filter($rows,fn($r)=>$filter==='todos'||$r['status']===$filter);?>
<div class="page-heading"><p class="eyebrow">GESTIÓN DE SORTEOS</p><div class="raffle-heading-row"><h1>Sorteos</h1><button class="btn primary" type="button" data-open="raffle-dialog">＋ Crear sorteo</button></div><p>Administra los premios, boletos y estados de tus sorteos.</p></div>
