<div class="raffle-summary" role="group" aria-label="Resumen de sorteos" tabindex="0">
    <span title="Sorteos registrados">Total: <strong><?=number_format($counts['todos'])?></strong></span>
    <span title="En curso">Activos: <strong><?=number_format($counts['activo'])?></strong></span>
