<section class="panel raffle-list-panel"><div class="section-heading"><h2>Listado de sorteos</h2><p>Selecciona un estado o busca un sorteo.</p></div><div class="tabs"><?php foreach(['todos'=>'Todos','activo'=>'Activos','borrador'=>'Borradores','finalizado'=>'Finalizados'] as $s=>$label): ?><a class="<?=$filter===$s?'active':''?>" href="<?=h(url('sorteos',['status'=>$s]))?>"><?=h($label)?> <span><?=$counts[$s]?></span></a><?php endforeach; ?></div><?php if(!$filtered):empty_state('No hay sorteos','Crea un nuevo sorteo o selecciona otro filtro.');else: ?><div class="table-wrap"><table id="raffle-table"><thead><tr><th>Sorteo</th><th>Tipo</th><th>Boletos</th><th>Valor</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($filtered as $r):$id=$r['id'];?><tr><td><div class="item"><?php photo($id,$r['first_photo']);?><div><strong><?=h($r['title'])?></strong><small>#<?=h(substr($id,0,8))?> · <?=h(substr($r['created_at'],0,10))?></small></div></div></td><td><?=h(ucfirst($r['type']))?></td><td><strong><?=number_format((int)$r['registered'])?></strong> / <?=number_format((int)$r['ticket_count'])?><progress max="<?=(int)$r['ticket_count']?>" value="<?=(int)$r['registered']?>"></progress></td><td><?=money($r['ticket_price_cents'])?></td><td><?=chip($r['status'])?></td><td><div class="actions"><button type="button" class="btn small secondary" data-view-raffle="<?=h(json_encode($r,JSON_INVALID_UTF8_SUBSTITUTE))?>">Ver</button><a class="btn small secondary" href="<?=h(url('participantes',['id'=>$id]))?>">Participantes</a><?php if($r['status']==='borrador'):?><button class="btn small secondary" type="button" data-edit-raffle="<?=h(json_encode($r,JSON_INVALID_UTF8_SUBSTITUTE))?>">Editar</button><?php form_action('activate',$id,'Activar','positive',null,'¿Activar el sorteo? No se podrán editar sus condiciones.');form_action('delete_raffle',$id,'Eliminar','danger',null,'¿Eliminar este borrador?');elseif($r['status']==='activo'):form_action('finish',$id,'Finalizar','secondary',null,'¿Cerrar el sorteo definitivamente?');endif;?></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<dialog id="raffle-dialog"><form method="post" enctype="multipart/form-data" id="raffle-form"><div class="dialog-head"><h2 id="raffle-title">Crear sorteo</h2><button type="button" class="close" data-close aria-label="Cerrar">×</button></div><div class="dialog-body"><?=csrf()?><input type="hidden" name="action" value="save_raffle"><input type="hidden" name="raffle_id" value="0"><label>Título<input name="title" required maxlength="180" placeholder="Ej. Consola de videojuegos"></label><label>Descripción<textarea name="description" rows="3" maxlength="10000" placeholder="Describe el premio y las condiciones"></textarea></label><label>Fotografías (hasta 3)</label><div class="photo-grid"><?php for($i=1;$i<=3;$i++): ?><div class="photo-box"><label for="photo<?=$i?>"><img class="preview" alt="Vista previa" hidden><span>＋ Foto <?=$i?></span></label><input type="file" name="photo<?=$i?>" id="photo<?=$i?>" accept="image/jpeg,image/png,image/webp"><label class="check remove" hidden><input type="checkbox" name="remove_photo<?=$i?>"> Quitar foto</label></div><?php endfor;?></div><p class="muted tiny">JPG, PNG o WebP. Máximo 2 MB por fotografía.</p><label>Tipo de sorteo<select name="type"><option value="producto">Producto</option><option value="dinero">Dinero</option></select></label><div class="form-grid"><label>Número de boletos<input name="ticket_count" type="number" min="1" max="1000000" required value="100"></label><label>Valor del boleto ($)<input name="price" type="number" min="0.01" max="1000000" step="0.01" required value="1.00"></label></div><div class="preview-total"><span>Ingreso potencial</span><strong id="potential">$100,00</strong></div><p class="muted tiny">Se guarda como borrador. Podrás activarlo desde el listado.</p></div><div class="dialog-foot"><button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn primary" type="submit">Guardar sorteo</button></div></form></dialog>
